"""
tools/dev/gen_app_map.py

Writes data/app_map.json (the curated "Windows app -> what to use on HalOS" table read by core/app_match.py) from
the compact rows below. Edit a row here, then:  python tools/dev/gen_app_map.py

    a(name, kind, targets, winget ids, chocolatey ids, other names ("|" separated), alt=..., why=...)

kind:    native | wine | web | alternative | none | not_needed
targets: best first, space separated: featured:<Store pick> repo:<Arch package> flatpak:<Flathub id> aur:<AUR package>
         winget:<Windows build to run with Wine> url:<official Linux download, or the web app>
A name ending in "*" in the other-names column matches as a prefix ("intel(r)*").
"""

import json
from pathlib import Path

N, W, WEB, ALT, NO, SKIP = "native", "wine", "web", "alternative", "none", "not_needed"
E = []


def a(name, kind, targets="", w="", c="", m="", alt="", why="", pub=""):
    e = {"name": name, "kind": kind}
    if m:
        e["match"] = [x.strip().lower() for x in m.split("|")]
    if w:
        e["winget"] = w.split()
    if c:
        e["choco"] = c.split()
    if pub:
        e["publisher"] = pub
    if targets:
        e["targets"] = targets.split()
    if alt:
        e["alternative"] = alt
    if why:
        e["why"] = why
    E.append(e)


ADOBE = "Adobe's installer and licensing don't work under Wine."
